{VARIANT:Implementing retry logic with exponential backoff|Exponential backoff for retries|Retry with jitter}:

```python
import time
import random
from functools import wraps

def retry_with_backoff(
    max_retries: int = 5,
    base_delay: float = 0.5,
    max_delay: float = 60.0,
    exceptions: tuple = (Exception,),
):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(max_retries):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    if attempt == max_retries - 1:
                        raise
                    delay = min(
                        base_delay * (2 ** attempt) + random.uniform(0, 0.5),
                        max_delay,
                    )
                    time.sleep(delay)
        return wrapper
    return decorator

@retry_with_backoff(max_retries=4, exceptions=(ConnectionError, TimeoutError))
def call_external_api():
    ...
```

{VARIANT:The jitter|Adding random jitter} (`random.uniform(0, 0.5)`) prevents {VARIANT:a thundering herd|retry storms} when many clients back off simultaneously.

{VARIANT:Here's a clean implementation of a binary tree|Binary tree in Python|Binary search tree implementation}:

```python
from dataclasses import dataclass
from typing import Optional

@dataclass
class Node:
    value: int
    left: Optional['Node'] = None
    right: Optional['Node'] = None

class BST:
    def __init__(self):
        self.root: Optional[Node] = None

    def insert(self, value: int) -> None:
        def _insert(node, v):
            if node is None:
                return Node(v)
            if v < node.value:
                node.left = _insert(node.left, v)
            elif v > node.value:
                node.right = _insert(node.right, v)
            return node
        self.root = _insert(self.root, value)

    def contains(self, value: int) -> bool:
        node = self.root
        while node:
            if value == node.value:
                return True
            node = node.left if value < node.value else node.right
        return False

    def inorder(self) -> list[int]:
        result = []
        def _walk(node):
            if node:
                _walk(node.left)
                result.append(node.value)
                _walk(node.right)
        _walk(self.root)
        return result
```

