```python
import redis
import json
import time
from threading import Thread

r = redis.Redis(decode_responses=True)
QUEUE_KEY = 'tasks:default'

def enqueue(task_name: str, **kwargs) -> str:
    task = {'name': task_name, 'kwargs': kwargs, 'enqueued_at': time.time()}
    task_id = r.rpush(QUEUE_KEY, json.dumps(task))
    return str(task_id)

def worker(handlers: dict):
    print('Worker started, waiting for tasks...')
    while True:
        _, raw = r.blpop(QUEUE_KEY, timeout=0)
        task = json.loads(raw)
        handler = handlers.get(task['name'])
        if handler:
            try:
                handler(**task['kwargs'])
            except Exception as e:
                print(f"Task {task['name']} failed: {e}")
        else:
            print(f"Unknown task: {task['name']}")

# Usage
def send_email(to: str, subject: str):
    print(f'Sending email to {to}: {subject}')

Thread(target=worker, args=({'send_email': send_email},), daemon=True).start()
enqueue('send_email', to='user@example.com', subject='Welcome!')
```

