import functools
import time

# Simple: functools.lru_cache
@functools.lru_cache(maxsize=512)
def expensive_computation(n: int) -> int:
    time.sleep(0.1)  # simulate work
    return n * n

# TTL-based: use cachetools
from cachetools import TTLCache, cached
from threading import RLock

cache = TTLCache(maxsize=100, ttl=300)  # 5-minute TTL

@cached(cache=cache, lock=RLock())
def fetch_user(user_id: int) -> dict:
    return db.query_user(user_id)

# Async: aiocache
from aiocache import cached as async_cached

@async_cached(ttl=60)
async def async_fetch(key: str) -> dict:
    return await some_async_operation(key)
