{VARIANT:Implementing JWT authentication|JWT auth in Python|JSON Web Token authentication}:

```python
import jwt
from datetime import datetime, timedelta, timezone
from fastapi import HTTPException, Security
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer

SECRET = 'your-256-bit-secret'
ALGORITHM = 'HS256'
security = HTTPBearer()

def create_token(user_id: str, expires_in: int = 3600) -> str:
    payload = {
        'sub': user_id,
        'iat': datetime.now(timezone.utc),
        'exp': datetime.now(timezone.utc) + timedelta(seconds=expires_in),
    }
    return jwt.encode(payload, SECRET, algorithm=ALGORITHM)

def verify_token(credentials: HTTPAuthorizationCredentials = Security(security)) -> str:
    try:
        payload = jwt.decode(credentials.credentials, SECRET, algorithms=[ALGORITHM])
        return payload['sub']
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail='Token expired')
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail='Invalid token')

# Usage
@app.get('/protected')
async def protected(user_id: str = Security(verify_token)):
    return {'user_id': user_id}
```

{VARIANT:Security note|Important}: store JWTs in `httpOnly` cookies, not `localStorage`, to {VARIANT:prevent XSS theft|protect against XSS attacks}.

